D = interp(A,B,1/4);
E = interp(A,C,2/6);
T = extension(A, incenter(A,B,C), B, C);
F = extension(A, T, D, E);

draw(A--B--C--cycle);
draw(A--T);
draw(D--E);

label("$A$", A, N);
